#!/usr/bin/env node
// generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
// Проверки памяти и конфигурации workspace: pass/fail, ничего не пишет.
//
//   node .claude/bin/workspace-check.mjs            — все проверки, код 1 при любом fail
//   node .claude/bin/workspace-check.mjs --list     — перечень проверок
//
// Корень — каталог над .claude/ либо WORKSPACE_ROOT (для фикстур). Проверки написаны под
// контракт .claude/workspace.json и правила charter: ключи и типы workspace.json, репозитории
// по правилу обхода, каталоги кода и рабочих деревьев под .gitignore корня, битые ссылки на файлы
// памяти, неподставленный слот {{…}} в charter, ролях и памяти, файл вне закрытого списка в memory/tasks/<КОД>/, frontmatter агентов против таблицы
// «Состав», пункт техдолга без статуса и отставший индекс, память ролей вне
// feedback_*/MEMORY.md, settings.json под версией.

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { findRoot, loadWorkspace, SAFE_NAME } from './lib/workspace.mjs';
import { loadGitSettings } from './lib/git.mjs';

if (process.argv[2] === '-h' || process.argv[2] === '--help') {
  const lines = fs.readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(2);
  const end = lines.findIndex((l) => !l.startsWith('//'));
  process.stdout.write(lines.slice(0, end).map((l) => l.replace(/^\/\/ ?/, '')).join('\n') + '\n');
  process.exit(0);
}

const here = path.dirname(fileURLToPath(import.meta.url));
const root = findRoot(here);
const ws = loadWorkspace(root);
const cfg = ws.config;
const rel = (p) => path.relative(root, p).replace(/\\/g, '/');
const read = (p) => fs.readFileSync(p, 'utf8');
const exists = (p) => fs.existsSync(p);
const tasksAbs = path.join(root, cfg.tasksDir);
const under = (p, dir) => p === dir || p.startsWith(dir + path.sep);

function walk(dir, filter) {
  const out = [];
  if (!exists(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...walk(p, filter));
    else if (!filter || filter(p)) out.push(p);
  }
  return out;
}

const checks = [];
const check = (name, fn) => checks.push({ name, fn });

check('.claude/workspace.json по контракту: ключи и типы', () => {
  if (!ws.exists) return ['.claude/workspace.json нет — скрипты работают на дефолтах'];
  return ws.problems.map((p) => p.msg);
});

// Сеть не трогается: какая ветка по умолчанию на сервере и есть ли там master и main,
// проверяет node .claude/bin/git-base.mjs <репо> в момент работы.
check('.claude/git-settings.json: у каждого репозитория профиль, личный файл под .gitignore', () => {
  const gs = loadGitSettings(root);
  const bad = gs.problems.map((p) => p.msg);
  if (!gs.exists) return [...bad, '.claude/git-settings.json нет — все репозитории идут как main-default'];
  for (const r of ws.repos) if (!(r.name in gs.repos)) bad.push(`${r.name}: профиля нет — идёт как main-default`);
  for (const name of Object.keys(gs.repos)) if (!ws.repos.some((r) => r.name === name)) bad.push(`repos.${name}: такого репозитория в workspace нет`);
  if (gs.localExists) {
    try {
      execFileSync('git', ['-C', root, 'check-ignore', '-q', '.claude/git-settings.local.json'], { stdio: 'ignore' });
    } catch {
      bad.push('.claude/git-settings.local.json не под .gitignore — ревьюеры личные');
    }
  }
  return bad;
});

check('репозитории находятся обходом, имена пригодны для скриптов .claude/bin/', () => {
  const bad = [];
  if (!exists(path.join(root, cfg.projectsDir))) bad.push(`каталога ${cfg.projectsDir}/ нет — код лежит в ${cfg.projectsDir}/<имя>/`);
  else if (!ws.repos.length) bad.push(`в ${cfg.projectsDir}/ нет ни одного каталога с .git`);
  for (const r of ws.repos) {
    if (!SAFE_NAME.test(r.name)) bad.push(`${r.path}: имя «${r.name}» вне [A-Za-z0-9_.-] — скрипты его пропустят`);
  }
  return bad;
});

// Источник совпадения должен быть .gitignore внутри репозитория: .git/info/exclude
// и глобальный excludesfile есть не на каждой машине.
// Корень workspace — репозиторий конфигурации и памяти: код и рабочие деревья в его историю
// не попадают.
check('каталоги кода и рабочих деревьев стоят в .gitignore корня workspace', () => {
  const bad = [];
  for (const dir of [cfg.projectsDir, cfg.worktreesDir]) {
    let out;
    try {
      out = execFileSync('git', ['-C', root, 'check-ignore', '-v', '--no-index', '--', `${dir}/`], { stdio: 'pipe' }).toString().trim();
    } catch (e) {
      bad.push(e.status === 1 ? `${dir}/ не игнорируется — допиши в .gitignore строку /${dir}/` : `git check-ignore: ${String(e.stderr || e.message).trim()}`);
      continue;
    }
    const [source, , pattern] = out.split('\t')[0].split(':');
    if (pattern?.startsWith('!')) bad.push(`${dir}/ снят с игнора правилом ${source}: ${pattern}`);
    else if (path.isAbsolute(source) || /^[A-Za-z]$/.test(source) || path.basename(source) !== '.gitignore') {
      bad.push(`${dir}/ игнорируется только правилом ${source} — на другой машине его не будет, нужна строка в .gitignore`);
    }
  }
  return bad;
});

// Ссылки на файлы памяти и конфигурации: `memory/…`, `.claude/…` в обратных кавычках
// и markdown-ссылки — файл должен существовать. Шаблоны с <КОД>, * и NNN пропускаются.
check('ссылки на файлы памяти и .claude не битые', () => {
  const files = [
    ...walk(path.join(root, 'memory'), (p) => p.endsWith('.md') && !under(p, tasksAbs)),
    ...walk(path.join(root, '.claude'), (p) => p.endsWith('.md') && !/agent-memory/.test(p)),
    path.join(root, 'CLAUDE.md'),
    path.join(root, 'README.md'),
  ].filter(exists);
  const broken = [];
  const re = /`((?:memory|\.claude)\/[A-Za-z0-9_./-]+?\.(?:md|mjs|sh|json|html))`|\]\(((?:\.\.\/|\.\/)?[A-Za-z0-9_./-]+?\.md)(?:#[^)]*)?\)/g;
  for (const f of files) {
    const text = read(f);
    let m;
    while ((m = re.exec(text))) {
      const target = m[1] ?? m[2];
      if (/[<*]|NNN|<КОД>/.test(target)) continue;
      // Личные файлы доступов существуют не на каждой машине.
      if (/-settings\.json$|settings\.local\.json$/.test(target)) continue;
      const abs = m[1] ? path.join(root, target) : path.resolve(path.dirname(f), target);
      if (!exists(abs)) broken.push(`${rel(f)}: ${target}`);
    }
  }
  return broken;
});

// Слот шаблона, который setup не подставил и не убрал, роль читает как текст инструкции.
check('в сгенерированных файлах нет неподставленных слотов {{…}}', () => {
  const files = [
    path.join(root, 'CLAUDE.md'),
    path.join(root, '.claude', 'team-charter.md'),
    path.join(root, '.claude', 'team-lead.md'),
    ...walk(path.join(root, '.claude', 'agents'), (p) => p.endsWith('.md')),
    ...walk(path.join(root, '.claude', 'rules'), (p) => p.endsWith('.md')),
    ...walk(path.join(root, 'memory'), (p) => p.endsWith('.md') && !under(p, tasksAbs)),
  ].filter(exists);
  const bad = [];
  for (const f of files) {
    read(f).split('\n').forEach((line, i) => {
      for (const m of line.matchAll(/\{\{([A-Z0-9_]+)\}\}/g)) bad.push(`${rel(f)}:${i + 1}: {{${m[1]}}}`);
    });
  }
  return bad;
});

check(`в ${cfg.tasksDir}/<КОД>/ только файлы закрытого списка`, () => {
  const allowed = new Set([
    'design-brief.md', 'plan-delta.md', 'test-cases.md', 'bug-log.md', 'review-report.md',
    'handover.md', 'preflight.md', 'git-flow.md', 'audit-report.md',
  ]);
  const bad = [];
  if (!exists(tasksAbs)) return bad;
  for (const task of fs.readdirSync(tasksAbs, { withFileTypes: true })) {
    if (!task.isDirectory()) { bad.push(`${cfg.tasksDir}/${task.name}: файл вне папки задачи`); continue; }
    const dir = path.join(tasksAbs, task.name);
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) {
        if (!['tracker', 'figma', 'screenshots'].includes(e.name)) bad.push(`${cfg.tasksDir}/${task.name}/${e.name}/: каталог вне списка`);
        continue;
      }
      if (allowed.has(e.name)) continue;
      if (e.name === `${task.name}-qa.html`) continue;
      bad.push(`${cfg.tasksDir}/${task.name}/${e.name}: не в закрытом списке`);
    }
  }
  return bad;
});

// «Модели:» — строка вида «a/b — opus; c — sonnet; d — haiku. Пояснение…»: роли через
// «/» или «,», раскладки через «;», пояснение после первой точки в разбор не идёт.
function parseModels(charter) {
  const m = charter.match(/\*\*Модели:\*\*([\s\S]*?)(?:\r?\n\s*\r?\n|$)/);
  const map = new Map();
  if (!m) return map;
  const head = m[1].replace(/\r?\n/g, ' ').split(/\.\s/)[0];
  for (const part of head.split(';')) {
    const mm = part.match(/^\s*(.+?)\s+—\s+([a-z0-9-]+)/);
    if (!mm) continue;
    for (const role of mm[1].split(/[/,]/)) map.set(role.replace(/[`\s]/g, ''), mm[2]);
  }
  return map;
}

const BUILTIN_AGENTS = new Set(['Explore', 'Plan', 'general-purpose']);

check('frontmatter агентов совпадает с таблицей «Состав» charter', () => {
  const charterPath = path.join(root, '.claude', 'team-charter.md');
  if (!exists(charterPath)) return ['нет .claude/team-charter.md'];
  const charter = read(charterPath);
  const section = charter.split(/^## Состав\s*$/m)[1]?.split(/^## /m)[0];
  if (!section) return ['в charter нет раздела «## Состав»'];
  const lines = section.split(/\r?\n/).filter((l) => /^\|/.test(l));
  const cellsOf = (l) => l.split('|').map((c) => c.trim());
  // Заголовок колонки может стоять в обратных кавычках: `subagent_type`.
  const header = lines.length ? cellsOf(lines[0]).map((c) => c.replace(/`/g, '')) : [];
  const agentCol = header.indexOf('subagent_type');
  const skillsCol = header.indexOf('Skills');
  if (agentCol === -1 || skillsCol === -1) return ['в таблице «Состав» нет колонок subagent_type и Skills'];
  const models = parseModels(charter);
  // Universal-скилы charter (строка «**Universal skills:**») разрешены во frontmatter любой роли
  // без записи в колонку Skills: предзагрузка общего стиля — решение проекта, не расхождение.
  const universal = new Set(
    [...(charter.match(/^\*\*Universal skills:\*\*(.*)$/m)?.[1] ?? '').matchAll(/`([^`]+)`/g)].map((m) => m[1].trim()),
  );
  const bad = [];
  for (const row of lines.slice(1)) {
    if (/^\|[\s|:-]+\|$/.test(row)) continue;
    const cells = cellsOf(row);
    const role = cells[1].replace(/`/g, '');
    const agent = cells[agentCol].replace(/`/g, '');
    if (BUILTIN_AGENTS.has(agent)) continue;
    const skillsCell = cells[skillsCol].replace(/`/g, '');
    const skills = ['—', '-', ''].includes(skillsCell) ? [] : skillsCell.split(',').map((s) => s.trim());
    const file = path.join(root, '.claude', 'agents', `${agent}.md`);
    if (!exists(file)) { bad.push(`${role}: нет файла .claude/agents/${agent}.md`); continue; }
    const fm = read(file).match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1] ?? '';
    const fmModel = fm.match(/^model:\s*(\S+)/m)?.[1];
    const fmSkills = (fm.match(/^skills:\s*\[([^\]]*)\]/m)?.[1] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
    const expectedModel = models.get(role);
    if (expectedModel && fmModel !== expectedModel) bad.push(`${agent}: model ${fmModel} в frontmatter, ${expectedModel} в charter`);
    for (const s of skills) if (!fmSkills.includes(s)) bad.push(`${agent}: skill ${s} из charter нет в frontmatter`);
    for (const s of fmSkills) if (!skills.includes(s) && !universal.has(s)) bad.push(`${agent}: skill ${s} в frontmatter, в charter нет`);
    if (/^effort:/m.test(fm)) bad.push(`${agent}: effort во frontmatter — уровень задаёт team-lead при вызове`);
  }
  return bad;
});

check('пункты техдолга со статусом, индекс актуален', () => {
  try {
    execFileSync(process.execPath, [path.join(here, 'tech-debt-index.mjs'), '--check'], { stdio: 'pipe', env: { ...process.env, WORKSPACE_ROOT: root } });
    return [];
  } catch (e) {
    return [String(e.stderr || e.stdout || e.message).trim()];
  }
});

check('память ролей — только feedback_*.md и MEMORY.md', () => {
  const dir = path.join(root, '.claude', 'agent-memory');
  return walk(dir).filter((p) => !/(^|[\\/])(MEMORY\.md|feedback_[^\\/]+\.md)$/.test(p)).map(rel);
});

check('.claude/scripts/ упразднён — скрипты только в .claude/bin/', () => (exists(path.join(root, '.claude', 'scripts')) ? ['.claude/scripts/ существует'] : []));

// Проверяется «не игнорируется», а не «закоммичен»: сразу после setup файл ещё не в коммите
// (setup не коммитит), но командный settings.json обязан доехать до коллег с репозиторием.
check('.claude/settings.json с permissions.deny и не под gitignore', () => {
  const bad = [];
  const p = path.join(root, '.claude', 'settings.json');
  if (!exists(p)) return ['.claude/settings.json отсутствует'];
  let json;
  try { json = JSON.parse(read(p)); } catch (e) { return [`settings.json: ${e.message}`]; }
  if (!json.permissions?.deny?.length) bad.push('нет permissions.deny');
  let ignored = false;
  try {
    execFileSync('git', ['-C', root, 'check-ignore', '-q', '.claude/settings.json'], { stdio: 'pipe' });
    ignored = true;
  } catch { /* код 1 — не игнорируется, это норма */ }
  if (ignored) bad.push('settings.json под gitignore — env, deny и общий allow не доедут до коллег');
  return bad;
});

// CLAUDE.md вложенного репозитория Claude Code подгружает сам, как только роль открыла файл
// в этом каталоге, — и молча подменяет роли факты памяти. Поэтому каждый такой файл (и его
// копии в рабочих деревьях) закрыт маской claudeMdExcludes: исключений нет.
const isDirSafe = (p) => { try { return fs.statSync(p).isDirectory(); } catch { return false; } };
const globToRegExp = (glob) => new RegExp(`^${glob
  .replace(/[.+^${}()|[\]\\]/g, '\\$&')
  .replace(/\*\*\//g, '\u0000')
  .replace(/\*\*/g, '\u0001')
  .replace(/\*/g, '[^/]*')
  .replace(/\?/g, '[^/]')
  .replace(/\u0000/g, '(?:.*/)?')
  .replace(/\u0001/g, '.*')}$`);

check('CLAUDE.md вложенных репозиториев и рабочих деревьев закрыты маской claudeMdExcludes', () => {
  const settingsPath = path.join(root, '.claude', 'settings.json');
  let masks = [];
  try { masks = JSON.parse(read(settingsPath)).claudeMdExcludes ?? []; } catch { /* JSON проверяет соседняя проверка */ }
  const patterns = masks.filter((m) => typeof m === 'string').map(globToRegExp);
  const candidates = [];
  for (const r of ws.repos) {
    for (const f of ['CLAUDE.md', path.join('.claude', 'CLAUDE.md')]) candidates.push({ repo: r.name, file: path.join(root, r.path, f) });
  }
  const wtBase = path.join(root, cfg.worktreesDir);
  if (isDirSafe(wtBase)) {
    for (const code of fs.readdirSync(wtBase)) {
      const codeDir = path.join(wtBase, code);
      if (!isDirSafe(codeDir)) continue;
      for (const repo of fs.readdirSync(codeDir)) candidates.push({ repo, file: path.join(codeDir, repo, 'CLAUDE.md') });
    }
  }
  const bad = [];
  for (const { repo, file } of candidates) {
    if (!exists(file)) continue;
    const relPath = rel(file);
    const absPath = file.replace(/\\/g, '/');
    if (patterns.some((p) => p.test(relPath) || p.test(absPath))) continue;
    bad.push(`${relPath}: не закрыт маской claudeMdExcludes в .claude/settings.json (форма — **/${repo}/CLAUDE.md)`);
  }
  return bad;
});

// Правило живёт у владельца: фраза-маркер встречается только в файле-владельце
// (таблица «Владельцы правил» в memory/MEMORY.md: | маркер | владелец |). Нет таблицы —
// проверять нечего: её заводит проект, а не setup.
check('фразы-маркеры правил — только в файле-владельце', () => {
  const indexPath = path.join(root, 'memory', 'MEMORY.md');
  if (!exists(indexPath)) return [];
  const section = read(indexPath).split(/^### Владельцы правил/m)[1];
  if (!section) return [];
  const rows = section.split(/\r?\n/).filter((l) => /^\| `/.test(l));
  const bad = [];
  const corpus = [
    ...walk(path.join(root, 'memory'), (p) => p.endsWith('.md') && !under(p, tasksAbs)),
    ...walk(path.join(root, '.claude'), (p) => p.endsWith('.md') && !/agent-memory/.test(p)),
  ];
  for (const row of rows) {
    const cells = row.split('|').map((c) => c.trim());
    const marker = cells[1].replace(/^`|`$/g, '');
    const owners = cells[2].split(',').map((c) => c.trim().replace(/`/g, ''));
    for (const f of corpus) {
      const r = rel(f);
      if (owners.some((o) => r === o || r.endsWith('/' + o)) || r === 'memory/MEMORY.md') continue;
      if (read(f).includes(marker)) bad.push(`«${marker}» в ${r}, владелец ${owners.join(', ')}`);
    }
  }
  return bad;
});

if (process.argv.includes('--list')) {
  for (const c of checks) console.log(`- ${c.name}`);
  process.exit(0);
}

let failed = 0;
for (const c of checks) {
  let problems;
  try { problems = c.fn(); } catch (e) { problems = [`исключение: ${e.message}`]; }
  if (problems.length === 0) {
    console.log(`PASS  ${c.name}`);
  } else {
    failed++;
    console.log(`FAIL  ${c.name}`);
    for (const p of problems.slice(0, 40)) console.log(`      ${p}`);
    if (problems.length > 40) console.log(`      … ещё ${problems.length - 40}`);
  }
}
console.log(failed ? `\n${failed} из ${checks.length} проверок красные` : `\nвсе ${checks.length} проверок зелёные`);
process.exit(failed ? 1 : 0);
